export const APP_PACK_SOURCES: Record<string, string> = {
  "achievements": "// @ts-nocheck\n// Card UI source: React and useYumina are injected globals at runtime.\n//\n// App pack: Achievements — medals the story awards for memorable moments,\n// plus a few locked hints of what the player could still earn.\n// The AI writes `app_achievements`; this file only draws it.\n\nconst LANG = \"__YUMINA_APP_LANG__\";\nconst VAR = \"app_achievements\";\n\nconst TABLE = {\n  zh: {\n    name: \"成就\", unlocked: \"已解锁 {n} 个\", locked: \"还没解锁\", rare: \"稀有\", fresh: \"新\",\n    empty: \"还没有成就。做出让人记住的事，这里就会亮起来。\",\n  },\n  en: {\n    name: \"Achievements\", unlocked: \"{n} unlocked\", locked: \"Still locked\", rare: \"Rare\", fresh: \"NEW\",\n    empty: \"No achievements yet. Do something memorable and one lights up here.\",\n  },\n  es: {\n    name: \"Logros\", unlocked: \"{n} desbloqueados\", locked: \"Por desbloquear\", rare: \"Raro\", fresh: \"NUEVO\",\n    empty: \"Aún no hay logros. Haz algo memorable y aparecerá aquí.\",\n  },\n};\nconst T = TABLE[LANG] || TABLE.en;\n\nexport const app = { id: \"achievements\", icon: \"🏆\", name: T.name, variable: VAR, accent: \"#eab308\", accent2: \"#f97316\", lang: LANG };\n\nconst INK = \"#1b1e2b\";\nconst MUTED = \"#737891\";\n\n// Ids the player had already seen when the panel was last open: anything newer\n// is marked NEW until they have looked once.\nconst SEEN = (typeof window !== \"undefined\" && (window.__yumina_app_seen = window.__yumina_app_seen || {})) || {};\n\nexport default function Achievements() {\n  const api = useYumina();\n  const data = api.variables[VAR] || {};\n  const unlocked = Array.isArray(data.unlocked) ? data.unlocked : [];\n  const hints = Array.isArray(data.hints) ? data.hints : [];\n  const seenRef = React.useRef(SEEN[VAR]);\n\n  React.useEffect(() => { SEEN[VAR] = unlocked.map((a, i) => String(a.id || i)); });\n\n  if (unlocked.length === 0 && hints.length === 0) {\n    return (\n      <div style={{ padding: \"40px 28px\", textAlign: \"center\", color: MUTED, fontSize: 14, lineHeight: 1.7 }}>\n        <div style={{ fontSize: 40, marginBottom: 8 }}>🏆</div>{T.empty}\n      </div>\n    );\n  }\n\n  const total = unlocked.length + hints.length;\n  const pct = total ? Math.round((unlocked.length / total) * 100) : 0;\n  const seen = seenRef.current;\n  const isNew = (a, i) => Array.isArray(seen) && !seen.includes(String(a.id || i));\n\n  return (\n    <div style={{ padding: 14, display: \"grid\", gap: 12 }}>\n      <div style={{ borderRadius: 18, padding: 16, background: \"linear-gradient(135deg, #fff7db, #ffe9d2)\", border: \"1px solid #f6e2b3\", display: \"flex\", alignItems: \"center\", gap: 14 }}>\n        <span style={{ width: 58, height: 58, borderRadius: 29, flexShrink: 0, display: \"grid\", placeItems: \"center\",\n          background: \"conic-gradient(#f59e0b \" + pct * 3.6 + \"deg, #f3e6c8 0deg)\" }}>\n          <span style={{ width: 46, height: 46, borderRadius: 23, background: \"#fffaf0\", display: \"grid\", placeItems: \"center\", fontSize: 14, fontWeight: 800, color: \"#b45309\" }}>{pct}%</span>\n        </span>\n        <span>\n          <b style={{ display: \"block\", fontSize: 17, color: INK }}>{T.unlocked.replace(\"{n}\", String(unlocked.length))}</b>\n          <span style={{ fontSize: 12.5, color: \"#9a6a1c\" }}>{unlocked.length} / {total}</span>\n        </span>\n      </div>\n\n      {unlocked.length > 0 ? (\n        <div style={{ display: \"grid\", gap: 8 }}>\n          {unlocked.slice().reverse().map((a, ri) => {\n            const i = unlocked.length - 1 - ri;\n            const fresh = isNew(a, i);\n            return (\n              <div key={a.id || i} style={{ borderRadius: 16, padding: a.rare ? 2 : 0,\n                background: a.rare ? \"linear-gradient(120deg, #f59e0b, #f472b6, #8b5cf6, #22d3ee, #f59e0b)\" : \"transparent\" }}>\n                <div style={{ borderRadius: a.rare ? 14 : 16, background: \"#fff\", border: a.rare ? \"none\" : \"1px solid \" + (fresh ? \"#f6c453\" : \"#eceef4\"), boxShadow: fresh ? \"0 0 0 3px rgba(246,196,83,0.25)\" : \"0 1px 2px rgba(20,24,40,0.05)\", padding: 12, display: \"flex\", alignItems: \"center\", gap: 12 }}>\n                  <span style={{ width: 48, height: 48, borderRadius: 24, flexShrink: 0, display: \"grid\", placeItems: \"center\", fontSize: 24,\n                    background: \"radial-gradient(circle at 35% 30%, #fff3b0, #f5c542 55%, #d99a0b)\", boxShadow: \"inset 0 -2px 4px rgba(150,90,0,0.35), 0 2px 6px rgba(217,154,11,0.35)\" }}>\n                    {a.icon || \"🏅\"}\n                  </span>\n                  <span style={{ flex: 1, minWidth: 0 }}>\n                    <span style={{ display: \"flex\", alignItems: \"center\", gap: 6, flexWrap: \"wrap\" }}>\n                      <b style={{ fontSize: 15, color: INK }}>{String(a.title || \"\")}</b>\n                      {fresh ? <span style={{ fontSize: 10.5, fontWeight: 800, padding: \"1px 7px\", borderRadius: 99, background: \"#ff3b4e\", color: \"#fff\" }}>{T.fresh}</span> : null}\n                      {a.rare ? <span style={{ fontSize: 10.5, fontWeight: 800, padding: \"1px 7px\", borderRadius: 99, background: \"#f3e8ff\", color: \"#7c3aed\" }}>✦ {T.rare}</span> : null}\n                    </span>\n                    {a.desc ? <span style={{ display: \"block\", fontSize: 12.5, color: MUTED, marginTop: 2, lineHeight: 1.5 }}>{String(a.desc)}</span> : null}\n                  </span>\n                  {a.time ? <span style={{ fontSize: 11, color: \"#9aa0b4\", alignSelf: \"flex-start\", flexShrink: 0 }}>{String(a.time)}</span> : null}\n                </div>\n              </div>\n            );\n          })}\n        </div>\n      ) : null}\n\n      {hints.length > 0 ? (\n        <div style={{ display: \"grid\", gap: 8 }}>\n          <div style={{ fontSize: 12, color: MUTED, padding: \"4px 2px 0\" }}>{T.locked}</div>\n          {hints.map((h, i) => (\n            <div key={h.id || i} style={{ borderRadius: 16, background: \"#f7f8fb\", border: \"1px dashed #d9dce6\", padding: 12, display: \"flex\", alignItems: \"center\", gap: 12 }}>\n              <span style={{ width: 48, height: 48, borderRadius: 24, flexShrink: 0, display: \"grid\", placeItems: \"center\", fontSize: 20, background: \"#e9ebf1\", color: \"#9aa0b4\" }}>🔒</span>\n              <span style={{ flex: 1, minWidth: 0 }}>\n                <b style={{ display: \"block\", fontSize: 14.5, color: \"#9aa0b4\", letterSpacing: \".08em\" }}>???</b>\n                <span style={{ display: \"block\", fontSize: 12.5, color: MUTED, marginTop: 2, lineHeight: 1.5 }}>{String(h.hint || \"\")}</span>\n              </span>\n            </div>\n          ))}\n        </div>\n      ) : null}\n    </div>\n  );\n}\n",
  "bag": "// @ts-nocheck\n// Card UI source: React and useYumina are injected globals at runtime.\n//\n// App pack: Bag — wallet and belongings. The AI keeps the balance, a short\n// ledger of every money change, and the items the player carries. Tapping an\n// item shows what it is and offers \"Use\", which fills the chat box.\n\nconst LANG = \"__YUMINA_APP_LANG__\";\nconst VAR = \"app_bag\";\n\nconst TABLE = {\n  zh: {\n    name: \"背包\", balance: \"余额\", ledger: \"最近收支\", items: \"物品\", use: \"使用\", back: \"返回\",\n    draft: \"（使用{name}）\", empty: \"包里还是空的。得到的东西会自动放进来。\", noLedger: \"还没有收支记录。\",\n    rarity: { common: \"普通\", rare: \"稀有\", epic: \"史诗\", legendary: \"传说\" },\n  },\n  en: {\n    name: \"Bag\", balance: \"Balance\", ledger: \"Recent\", items: \"Items\", use: \"Use\", back: \"Back\",\n    draft: \"(uses {name}) \", empty: \"Nothing here yet. Things you get land here on their own.\", noLedger: \"No transactions yet.\",\n    rarity: { common: \"Common\", rare: \"Rare\", epic: \"Epic\", legendary: \"Legendary\" },\n  },\n  es: {\n    name: \"Mochila\", balance: \"Saldo\", ledger: \"Movimientos\", items: \"Objetos\", use: \"Usar\", back: \"Atrás\",\n    draft: \"(usa {name}) \", empty: \"Aún no hay nada. Lo que consigas aparecerá aquí solo.\", noLedger: \"Sin movimientos todavía.\",\n    rarity: { common: \"Común\", rare: \"Raro\", epic: \"Épico\", legendary: \"Legendario\" },\n  },\n};\nconst T = TABLE[LANG] || TABLE.en;\n\nexport const app = { id: \"bag\", icon: \"🎒\", name: T.name, variable: VAR, accent: \"#f5a524\", accent2: \"#f97316\", lang: LANG };\n\nconst INK = \"#1b1e2b\";\nconst MUTED = \"#737891\";\nconst RARITY = { common: \"#c9cdd9\", rare: \"#3d8bff\", epic: \"#9a5bff\", legendary: \"#f5a524\" };\nconst card = { borderRadius: 18, background: \"#fff\", border: \"1px solid #eceef4\", boxShadow: \"0 1px 2px rgba(20,24,40,0.05)\" };\n\nfunction money(n) {\n  const v = Number(n);\n  if (!Number.isFinite(v)) return String(n ?? \"\");\n  return v.toLocaleString(LANG === \"zh\" ? \"zh-CN\" : LANG === \"es\" ? \"es-ES\" : \"en-US\");\n}\n\nexport default function Bag({ close }) {\n  const api = useYumina();\n  const data = api.variables[VAR] || {};\n  const items = Array.isArray(data.items) ? data.items : [];\n  const ledger = Array.isArray(data.ledger) ? data.ledger : [];\n  const [openIdx, setOpenIdx] = React.useState(null);\n  const hasWallet = data.balance !== undefined && data.balance !== null && data.balance !== \"\";\n\n  const item = openIdx !== null ? items[openIdx] : null;\n  if (item) {\n    const rc = RARITY[item.rarity] || RARITY.common;\n    const name = String(item.name || \"\");\n    return (\n      <div style={{ padding: 14, display: \"grid\", gap: 12 }}>\n        <button type=\"button\" onClick={() => setOpenIdx(null)}\n          style={{ justifySelf: \"start\", border: \"none\", cursor: \"pointer\", background: \"#eef0f5\", color: \"#5b6075\", borderRadius: 10, padding: \"6px 12px\", fontSize: 13, fontWeight: 600 }}>\n          ‹ {T.back}\n        </button>\n        <div style={{ ...card, padding: 20, display: \"grid\", justifyItems: \"center\", gap: 10, textAlign: \"center\" }}>\n          <span style={{ width: 88, height: 88, borderRadius: 24, display: \"grid\", placeItems: \"center\", fontSize: 46, background: \"#f7f8fb\", border: \"3px solid \" + rc }}>{item.icon || \"📦\"}</span>\n          <b style={{ fontSize: 18, color: INK }}>{name}{Number(item.qty) > 1 ? \" ×\" + item.qty : \"\"}</b>\n          <span style={{ fontSize: 12, fontWeight: 700, color: rc === RARITY.common ? MUTED : rc }}>{T.rarity[item.rarity] || T.rarity.common}</span>\n          {item.note ? <p style={{ margin: 0, fontSize: 14, lineHeight: 1.65, color: INK }}>{String(item.note)}</p> : null}\n          <button type=\"button\" onClick={() => { api.setComposerDraft(T.draft.replace(\"{name}\", name)); if (close) close(); }}\n            style={{ marginTop: 4, border: \"none\", cursor: \"pointer\", borderRadius: 12, padding: \"10px 28px\", fontSize: 14, fontWeight: 800, color: \"#fff\", background: \"linear-gradient(135deg, #f5a524, #f97316)\" }}>\n            {T.use}\n          </button>\n        </div>\n      </div>\n    );\n  }\n\n  return (\n    <div style={{ padding: 14, display: \"grid\", gap: 12 }}>\n      {hasWallet ? (\n        <div style={{ borderRadius: 20, padding: \"16px 18px\", color: \"#fff\", background: \"linear-gradient(135deg, #f5a524, #f97316 60%, #ea580c)\", boxShadow: \"0 8px 20px rgba(249,115,22,0.28)\" }}>\n          <div style={{ fontSize: 12.5, opacity: 0.9, fontWeight: 600 }}>{T.balance}</div>\n          <div style={{ display: \"flex\", alignItems: \"baseline\", gap: 8, marginTop: 2 }}>\n            <b style={{ fontSize: 32, fontVariantNumeric: \"tabular-nums\", lineHeight: 1.15 }}>{money(data.balance)}</b>\n            {data.currency ? <span style={{ fontSize: 14, fontWeight: 700, opacity: 0.95 }}>{String(data.currency)}</span> : null}\n          </div>\n          <div style={{ marginTop: 12, background: \"rgba(255,255,255,0.95)\", borderRadius: 14, padding: \"4px 12px\" }}>\n            <div style={{ fontSize: 11.5, color: MUTED, padding: \"6px 0 2px\" }}>{T.ledger}</div>\n            {ledger.length === 0 ? <div style={{ fontSize: 12.5, color: MUTED, padding: \"4px 0 8px\" }}>{T.noLedger}</div> : null}\n            {ledger.slice(-5).reverse().map((l, i) => {\n              const amt = Number(l.amount) || 0;\n              return (\n                <div key={l.id || i} style={{ display: \"flex\", alignItems: \"center\", gap: 8, padding: \"7px 0\", borderTop: i ? \"1px solid #f0f1f5\" : \"none\" }}>\n                  <span style={{ flex: 1, minWidth: 0, fontSize: 13, color: INK, overflow: \"hidden\", textOverflow: \"ellipsis\", whiteSpace: \"nowrap\" }}>{String(l.what || \"\")}</span>\n                  {l.time ? <span style={{ fontSize: 11, color: MUTED }}>{String(l.time)}</span> : null}\n                  <b style={{ fontSize: 13, fontVariantNumeric: \"tabular-nums\", color: amt >= 0 ? \"#12925a\" : \"#d23b3b\" }}>{amt >= 0 ? \"+\" + money(amt) : \"−\" + money(Math.abs(amt))}</b>\n                </div>\n              );\n            })}\n          </div>\n        </div>\n      ) : null}\n\n      <b style={{ fontSize: 13, color: MUTED, padding: \"0 2px\" }}>{T.items}{items.length ? \" · \" + items.length : \"\"}</b>\n      {items.length === 0 ? (\n        <div style={{ padding: \"24px 24px\", textAlign: \"center\", color: MUTED, fontSize: 14, lineHeight: 1.7 }}>\n          <div style={{ fontSize: 40, marginBottom: 8 }}>🎒</div>{T.empty}\n        </div>\n      ) : (\n        <div style={{ display: \"grid\", gridTemplateColumns: \"repeat(auto-fill, minmax(84px, 1fr))\", gap: 10 }}>\n          {items.map((it, i) => {\n            const rc = RARITY[it.rarity] || RARITY.common;\n            return (\n              <button key={it.id || i} type=\"button\" onClick={() => setOpenIdx(i)} title={String(it.name || \"\")}\n                style={{ position: \"relative\", cursor: \"pointer\", border: \"2px solid \" + rc, borderRadius: 16, background: \"#fff\", padding: \"12px 6px 9px\", display: \"grid\", justifyItems: \"center\", gap: 5, boxShadow: \"0 1px 2px rgba(20,24,40,0.05)\" }}>\n                <span style={{ fontSize: 30, lineHeight: 1 }}>{it.icon || \"📦\"}</span>\n                <span style={{ fontSize: 12, color: INK, fontWeight: 600, maxWidth: \"100%\", overflow: \"hidden\", textOverflow: \"ellipsis\", whiteSpace: \"nowrap\" }}>{String(it.name || \"\")}</span>\n                {Number(it.qty) > 1 ? (\n                  <span style={{ position: \"absolute\", top: 5, right: 6, fontSize: 11, fontWeight: 800, color: \"#fff\", background: \"#1b1e2b\", borderRadius: 8, padding: \"0 5px\", lineHeight: \"16px\" }}>×{it.qty}</span>\n                ) : null}\n              </button>\n            );\n          })}\n        </div>\n      )}\n    </div>\n  );\n}\n",
  "journal": "// @ts-nocheck\n// Card UI source: React and useYumina are injected globals at runtime.\n//\n// App pack: Journal — the clues, secrets and goals the player has picked up.\n// The AI writes entries as the player learns things. The player can pin an\n// entry or add a note of their own here; neither costs a turn, and the AI\n// reads player notes (by \"player\") in the variable on the next one.\n\nconst LANG = \"__YUMINA_APP_LANG__\";\nconst VAR = \"app_journal\";\n\nconst TABLE = {\n  zh: {\n    name: \"线索笔记\", all: \"全部\", kinds: { clue: \"线索\", secret: \"秘密\", goal: \"目标\", note: \"笔记\" },\n    pin: \"置顶\", unpin: \"取消置顶\", add: \"写一条自己的笔记…\", addBtn: \"记下\", mine: \"我写的\",\n    empty: \"还没有记下什么。发现线索、知道秘密、接下目标时，会自动记在这里。\", none: \"这一类还没有内容。\",\n  },\n  en: {\n    name: \"Journal\", all: \"All\", kinds: { clue: \"Clue\", secret: \"Secret\", goal: \"Goal\", note: \"Note\" },\n    pin: \"Pin\", unpin: \"Unpin\", add: \"Write a note of your own…\", addBtn: \"Save\", mine: \"Mine\",\n    empty: \"Nothing written yet. Clues, secrets and goals are noted here as you come across them.\", none: \"Nothing of this kind yet.\",\n  },\n  es: {\n    name: \"Diario\", all: \"Todo\", kinds: { clue: \"Pista\", secret: \"Secreto\", goal: \"Objetivo\", note: \"Nota\" },\n    pin: \"Fijar\", unpin: \"Quitar\", add: \"Escribe una nota propia…\", addBtn: \"Guardar\", mine: \"Mía\",\n    empty: \"Aún no hay nada. Las pistas, secretos y objetivos se anotan aquí cuando los descubres.\", none: \"Todavía no hay nada de este tipo.\",\n  },\n};\nconst T = TABLE[LANG] || TABLE.en;\n\nexport const app = { id: \"journal\", icon: \"📝\", name: T.name, variable: VAR, accent: \"#6366f1\", accent2: \"#a855f7\", lang: LANG };\n\nconst INK = \"#1b1e2b\";\nconst MUTED = \"#737891\";\nconst KIND = {\n  clue: { icon: \"🔎\", strong: \"#2f6fd1\", soft: \"#e3ecff\" },\n  secret: { icon: \"🤫\", strong: \"#b4368a\", soft: \"#fbe3f2\" },\n  goal: { icon: \"🎯\", strong: \"#d9661f\", soft: \"#fdeadb\" },\n  note: { icon: \"📌\", strong: \"#5b5f73\", soft: \"#eceef4\" },\n};\n\nexport default function Journal() {\n  const api = useYumina();\n  const data = api.variables[VAR] || {};\n  const entries = Array.isArray(data.entries) ? data.entries : [];\n  const [filter, setFilter] = React.useState(\"all\");\n  const [draft, setDraft] = React.useState(\"\");\n\n  const save = (next) => api.patchVariables({ [VAR]: { ...data, entries: next } }).catch(() => {});\n  const togglePin = (i) => save(entries.map((e, j) => (j === i ? { ...e, pinned: !e.pinned } : e)));\n  const remove = (i) => save(entries.filter((_, j) => j !== i));\n  const add = () => {\n    const text = draft.trim();\n    if (!text) return;\n    save([...entries, { id: \"p\" + Date.now().toString(36), kind: \"note\", title: \"\", text, time: \"\", pinned: false, by: \"player\" }]);\n    setDraft(\"\");\n  };\n\n  // Pinned first, then newest first (the AI appends, so later = newer).\n  const shown = entries\n    .map((e, i) => ({ e, i }))\n    .filter(({ e }) => filter === \"all\" || (e.kind || \"note\") === filter)\n    .sort((a, b) => (b.e.pinned ? 1 : 0) - (a.e.pinned ? 1 : 0) || b.i - a.i);\n\n  const chip = (key, label, icon) => {\n    const on = filter === key;\n    return (\n      <button key={key} type=\"button\" onClick={() => setFilter(key)} aria-pressed={on}\n        style={{ border: \"none\", cursor: \"pointer\", borderRadius: 99, padding: \"6px 11px\", fontSize: 12.5, fontWeight: 700, whiteSpace: \"nowrap\", background: on ? \"#6366f1\" : \"#fff\", color: on ? \"#fff\" : MUTED, boxShadow: on ? \"none\" : \"inset 0 0 0 1px #e3e5ec\" }}>\n        {icon ? icon + \" \" : \"\"}{label}\n      </button>\n    );\n  };\n\n  return (\n    <div style={{ padding: 14, display: \"grid\", gap: 10 }}>\n      <div style={{ display: \"flex\", gap: 6, overflowX: \"auto\", paddingBottom: 2 }}>\n        {chip(\"all\", T.all)}\n        {Object.keys(KIND).map((k) => chip(k, T.kinds[k], KIND[k].icon))}\n      </div>\n\n      {entries.length === 0 ? (\n        <div style={{ padding: \"32px 22px\", textAlign: \"center\", color: MUTED, fontSize: 14, lineHeight: 1.7 }}>\n          <div style={{ fontSize: 40, marginBottom: 8 }}>📝</div>{T.empty}\n        </div>\n      ) : shown.length === 0 ? (\n        <p style={{ margin: \"8px 2px\", fontSize: 13, color: MUTED }}>{T.none}</p>\n      ) : null}\n\n      {shown.map(({ e, i }) => {\n        const k = KIND[e.kind] ? e.kind : \"note\";\n        const s = KIND[k];\n        const mine = e.by === \"player\";\n        return (\n          <div key={e.id || i} style={{ borderRadius: 16, background: \"#fff\", border: \"1px solid \" + (e.pinned ? \"#c7c9f7\" : \"#eceef4\"), boxShadow: \"0 1px 2px rgba(20,24,40,0.05)\", padding: \"12px 14px\", display: \"grid\", gap: 6 }}>\n            <div style={{ display: \"flex\", alignItems: \"center\", gap: 7, flexWrap: \"wrap\" }}>\n              <span style={{ fontSize: 11.5, fontWeight: 700, padding: \"2px 8px\", borderRadius: 99, background: s.soft, color: s.strong }}>{s.icon} {T.kinds[k]}</span>\n              {mine ? <span style={{ fontSize: 11, color: \"#6366f1\", fontWeight: 600 }}>{T.mine}</span> : null}\n              <span style={{ flex: 1 }} />\n              {e.time ? <span style={{ fontSize: 11, color: \"#9aa0b4\" }}>{String(e.time)}</span> : null}\n              <button type=\"button\" onClick={() => togglePin(i)} aria-pressed={!!e.pinned} title={e.pinned ? T.unpin : T.pin} aria-label={e.pinned ? T.unpin : T.pin}\n                style={{ border: \"none\", background: e.pinned ? \"#eef0ff\" : \"transparent\", borderRadius: 8, cursor: \"pointer\", fontSize: 14, padding: \"2px 6px\", opacity: e.pinned ? 1 : 0.45 }}>📌</button>\n              {mine ? (\n                <button type=\"button\" onClick={() => remove(i)} aria-label=\"×\"\n                  style={{ border: \"none\", background: \"transparent\", color: \"#9aa0b4\", cursor: \"pointer\", fontSize: 16, padding: \"0 2px\" }}>×</button>\n              ) : null}\n            </div>\n            {e.title ? <b style={{ fontSize: 15, color: INK }}>{String(e.title)}</b> : null}\n            {e.text ? <div style={{ fontSize: 13.5, lineHeight: 1.65, color: e.title ? \"#444a5e\" : INK, whiteSpace: \"pre-wrap\" }}>{String(e.text)}</div> : null}\n          </div>\n        );\n      })}\n\n      <div style={{ display: \"flex\", gap: 8, marginTop: 4 }}>\n        <input value={draft} onChange={(ev) => setDraft(ev.target.value)} onKeyDown={(ev) => { if (ev.key === \"Enter\") add(); }}\n          placeholder={T.add}\n          style={{ flex: 1, minWidth: 0, borderRadius: 12, border: \"1px solid #e3e5ec\", background: \"#fff\", color: INK, padding: \"10px 12px\", fontSize: 13.5, outline: \"none\" }} />\n        <button type=\"button\" onClick={add}\n          style={{ border: \"none\", borderRadius: 12, padding: \"0 16px\", fontWeight: 700, fontSize: 13, cursor: \"pointer\", background: \"#6366f1\", color: \"#fff\" }}>{T.addBtn}</button>\n      </div>\n    </div>\n  );\n}\n",
  "phone": "// @ts-nocheck\n// Card UI source: React and useYumina are injected globals at runtime.\n//\n// App pack: Phone — texting the characters, plus the posts they share.\n// The AI writes incoming texts and posts into `app_phone`. A text the player\n// sends is saved to the thread at once AND sent as a turn, so it shows in the\n// main chat and the character can answer. Likes and comments only touch the\n// variable: no turn, and the AI sees them next time.\n// The look follows the messenger people already use in each language:\n// green-on-grey for Chinese, blue bubbles for English, WhatsApp-style for Spanish.\n\nconst LANG = \"__YUMINA_APP_LANG__\";\nconst VAR = \"app_phone\";\n\nconst TABLE = {\n  zh: {\n    name: \"手机\", chats: \"消息\", moments: \"朋友圈\", noChats: \"还没有人发消息来。有人联系你时，对话会出现在这里。\",\n    noMoments: \"朋友圈还没有动态。\", say: \"发消息…\", send: \"发送\", me: \"我\",\n    action: \"（用手机发消息给{name}）{text}\", comment: \"评论…\", newChat: \"给谁发消息？输入名字\", start: \"开始\", likes: \"{n} 人觉得很赞\",\n  },\n  en: {\n    name: \"Phone\", chats: \"Messages\", moments: \"Moments\", noChats: \"No messages yet. When someone texts you, the conversation shows up here.\",\n    noMoments: \"Nothing posted yet.\", say: \"iMessage\", send: \"Send\", me: \"Me\",\n    action: \"(texts {name}) {text}\", comment: \"Add a comment…\", newChat: \"Text someone new — type a name\", start: \"Open\", likes: \"{n} likes\",\n  },\n  es: {\n    name: \"Teléfono\", chats: \"Chats\", moments: \"Momentos\", noChats: \"Aún no hay mensajes. Cuando alguien te escriba, la conversación aparecerá aquí.\",\n    noMoments: \"Nadie ha publicado todavía.\", say: \"Mensaje\", send: \"Enviar\", me: \"Yo\",\n    action: \"(le escribe a {name} por el móvil) {text}\", comment: \"Comentar…\", newChat: \"Escribir a alguien — pon un nombre\", start: \"Abrir\", likes: \"{n} me gusta\",\n  },\n};\nconst T = TABLE[LANG] || TABLE.en;\n\nconst SKINS = {\n  zh: { chatBg: \"#ededed\", mine: \"#95ec69\", mineText: \"#111\", theirs: \"#ffffff\", theirsText: \"#111\", avatarRadius: 6, accent: \"#07c160\", tick: false, bubbleRadius: 6 },\n  en: { chatBg: \"#ffffff\", mine: \"#0a84ff\", mineText: \"#fff\", theirs: \"#e9e9eb\", theirsText: \"#111\", avatarRadius: 99, accent: \"#0a84ff\", tick: false, bubbleRadius: 18 },\n  es: { chatBg: \"#efeae2\", mine: \"#d9fdd3\", mineText: \"#111\", theirs: \"#ffffff\", theirsText: \"#111\", avatarRadius: 99, accent: \"#00a884\", tick: true, bubbleRadius: 10 },\n};\nconst S = SKINS[LANG] || SKINS.en;\n\nexport const app = {\n  id: \"phone\", icon: \"💬\", name: T.name, variable: VAR, accent: \"#34d17a\", accent2: \"#12a867\", lang: LANG,\n  badge: (d) => {\n    const th = d && d.threads && typeof d.threads === \"object\" ? d.threads : {};\n    return Object.keys(th).reduce((n, k) => n + (Number(th[k] && th[k].unread) || 0), 0);\n  },\n};\n\nconst INK = \"#1b1e2b\";\nconst MUTED = \"#8a8fa3\";\nconst PALETTE = [\"#f29a1f\", \"#5b7cff\", \"#19b394\", \"#ff5f8f\", \"#9a5bff\", \"#1aa3e0\", \"#ef6a3a\"];\nfunction colorFor(key) {\n  let h = 0;\n  for (let i = 0; i < key.length; i++) h = (h * 31 + key.charCodeAt(i)) >>> 0;\n  return PALETTE[h % PALETTE.length];\n}\nfunction Avatar({ name, id, size }) {\n  const c = colorFor(id || name || \"?\");\n  const s = size || 44;\n  return (\n    <span style={{ width: s, height: s, borderRadius: S.avatarRadius === 99 ? s / 2 : S.avatarRadius, background: c, color: \"#fff\", display: \"grid\", placeItems: \"center\", fontWeight: 700, fontSize: s * 0.42, flexShrink: 0 }}>\n      {String(name || \"?\").slice(0, 1)}\n    </span>\n  );\n}\nfunction slug(name) {\n  const s = String(name).trim().toLowerCase().replace(/\\s+/g, \"_\").replace(/[^\\p{L}\\p{N}_]/gu, \"\");\n  return s || \"c\" + Date.now().toString(36);\n}\nconst field = { flex: 1, minWidth: 0, borderRadius: 20, border: \"1px solid #dfe2ea\", background: \"#fff\", color: INK, padding: \"9px 14px\", fontSize: 14, outline: \"none\" };\nconst sendBtn = { border: \"none\", borderRadius: 20, padding: \"0 16px\", fontWeight: 700, fontSize: 13.5, cursor: \"pointer\", background: S.accent, color: \"#fff\" };\n\nexport default function Phone() {\n  const api = useYumina();\n  const data = api.variables[VAR] || {};\n  const threads = data.threads && typeof data.threads === \"object\" ? data.threads : {};\n  const moments = Array.isArray(data.moments) ? data.moments : [];\n  const [tab, setTab] = React.useState(\"chats\");\n  const [openId, setOpenId] = React.useState(null);\n  const [draft, setDraft] = React.useState(\"\");\n  const [newName, setNewName] = React.useState(\"\");\n  const [comments, setComments] = React.useState({});\n  const bottomRef = React.useRef(null);\n\n  const save = (next) => api.patchVariables({ [VAR]: { ...data, ...next } }).catch(() => {});\n  const thread = openId ? threads[openId] : null;\n  const messages = thread && Array.isArray(thread.messages) ? thread.messages : [];\n\n  React.useEffect(() => {\n    if (openId && thread && thread.unread) save({ threads: { ...threads, [openId]: { ...thread, unread: 0 } } });\n    if (bottomRef.current) bottomRef.current.scrollIntoView({ block: \"end\" });\n  }, [openId, messages.length]);\n\n  const send = () => {\n    const text = draft.trim();\n    if (!text || !openId) return;\n    const t = threads[openId] || { name: openId, messages: [] };\n    const nextThread = { ...t, unread: 0, messages: [...(Array.isArray(t.messages) ? t.messages : []), { from: \"me\", text }] };\n    save({ threads: { ...threads, [openId]: nextThread } });\n    api.sendMessage(T.action.replace(\"{name}\", String(t.name || openId)).replace(\"{text}\", text));\n    setDraft(\"\");\n  };\n  const startChat = () => {\n    const name = newName.trim();\n    if (!name) return;\n    const existing = Object.keys(threads).find((k) => String(threads[k].name || k) === name);\n    const id = existing || slug(name);\n    if (!existing) save({ threads: { ...threads, [id]: { name, messages: [], unread: 0 } } });\n    setNewName(\"\");\n    setOpenId(id);\n  };\n  const toggleLike = (i) => save({ moments: moments.map((m, j) => (j === i ? { ...m, liked: !m.liked } : m)) });\n  const addComment = (i) => {\n    const text = String(comments[i] || \"\").trim();\n    if (!text) return;\n    save({ moments: moments.map((m, j) => (j === i ? { ...m, comments: [...(Array.isArray(m.comments) ? m.comments : []), { author: \"me\", text }] } : m)) });\n    setComments({ ...comments, [i]: \"\" });\n  };\n\n  // ── One conversation ──\n  if (openId) {\n    const name = String((thread && thread.name) || openId);\n    return (\n      <div style={{ display: \"flex\", flexDirection: \"column\", flex: 1, minHeight: 0, background: S.chatBg }}>\n        <div style={{ display: \"flex\", alignItems: \"center\", gap: 10, padding: \"9px 12px\", background: LANG === \"es\" ? \"#f0f2f5\" : \"rgba(255,255,255,0.92)\", borderBottom: \"1px solid #e3e5eb\" }}>\n          <button type=\"button\" onClick={() => setOpenId(null)} aria-label=\"Back\"\n            style={{ border: \"none\", background: \"transparent\", color: S.accent, cursor: \"pointer\", fontSize: 26, lineHeight: 1, padding: \"0 4px\" }}>‹</button>\n          <Avatar name={name} id={openId} size={32} />\n          <b style={{ fontSize: 15, color: INK }}>{name}</b>\n        </div>\n        <div style={{ flex: 1, minHeight: 0, overflowY: \"auto\", padding: \"14px 12px\", display: \"flex\", flexDirection: \"column\", gap: 8 }}>\n          {messages.map((m, i) => {\n            const mine = m.from === \"me\";\n            return (\n              <div key={i} style={{ display: \"flex\", gap: 8, alignItems: \"flex-end\", flexDirection: mine ? \"row-reverse\" : \"row\" }}>\n                {LANG === \"zh\" ? (mine ? <Avatar name={T.me} id=\"me\" size={34} /> : <Avatar name={name} id={openId} size={34} />) : null}\n                <div style={{ maxWidth: \"74%\", padding: \"8px 12px\", borderRadius: S.bubbleRadius, fontSize: 14.5, lineHeight: 1.5, whiteSpace: \"pre-wrap\", wordBreak: \"break-word\",\n                  background: mine ? S.mine : S.theirs, color: mine ? S.mineText : S.theirsText, boxShadow: LANG === \"en\" ? \"none\" : \"0 1px 1px rgba(0,0,0,0.06)\" }}>\n                  {String(m.text || \"\")}\n                  {m.time || (S.tick && mine) ? (\n                    <span style={{ display: \"block\", textAlign: \"right\", fontSize: 10.5, marginTop: 2, color: mine && LANG === \"en\" ? \"rgba(255,255,255,0.75)\" : \"#8a8f99\" }}>\n                      {m.time ? String(m.time) : \"\"}{S.tick && mine ? \" ✓✓\" : \"\"}\n                    </span>\n                  ) : null}\n                </div>\n              </div>\n            );\n          })}\n          <div ref={bottomRef} />\n        </div>\n        <div style={{ display: \"flex\", gap: 8, padding: 10, background: LANG === \"es\" ? \"#f0f2f5\" : \"#f7f7f7\", borderTop: \"1px solid #e3e5eb\" }}>\n          <input value={draft} onChange={(e) => setDraft(e.target.value)} onKeyDown={(e) => { if (e.key === \"Enter\" && !e.shiftKey) send(); }} placeholder={T.say} style={field} />\n          <button type=\"button\" onClick={send} style={sendBtn}>{T.send}</button>\n        </div>\n      </div>\n    );\n  }\n\n  const ids = Object.keys(threads);\n  const unreadTotal = app.badge(data);\n  const tabBtn = (key, label, badge) => (\n    <button type=\"button\" onClick={() => setTab(key)} aria-pressed={tab === key}\n      style={{ flex: 1, border: \"none\", cursor: \"pointer\", padding: \"8px 0\", fontSize: 14, fontWeight: 700, borderRadius: 10, background: tab === key ? \"#fff\" : \"transparent\", color: tab === key ? INK : MUTED, boxShadow: tab === key ? \"0 1px 3px rgba(20,24,40,0.12)\" : \"none\" }}>\n      {label}{badge ? <span style={{ marginLeft: 6, fontSize: 11, padding: \"0 6px\", borderRadius: 99, background: \"#ff3b4e\", color: \"#fff\" }}>{badge}</span> : null}\n    </button>\n  );\n\n  return (\n    <div style={{ padding: 14, display: \"grid\", gap: 12, alignContent: \"start\" }}>\n      <div style={{ display: \"flex\", gap: 4, padding: 3, borderRadius: 12, background: \"#e6e8ee\" }}>\n        {tabBtn(\"chats\", T.chats, unreadTotal)}\n        {tabBtn(\"moments\", T.moments, 0)}\n      </div>\n\n      {tab === \"chats\" ? (\n        <>\n          <div style={{ borderRadius: 16, background: \"#fff\", border: \"1px solid #eceef4\", overflow: \"hidden\" }}>\n            {ids.length === 0 ? <p style={{ margin: 0, padding: \"22px 18px\", fontSize: 13.5, color: MUTED, lineHeight: 1.7, textAlign: \"center\" }}>{T.noChats}</p> : null}\n            {ids.map((id, n) => {\n              const t = threads[id] || {};\n              const msgs = Array.isArray(t.messages) ? t.messages : [];\n              const last = msgs[msgs.length - 1];\n              const name = String(t.name || id);\n              const unread = Number(t.unread) || 0;\n              return (\n                <button key={id} type=\"button\" onClick={() => setOpenId(id)}\n                  style={{ all: \"unset\", cursor: \"pointer\", display: \"flex\", alignItems: \"center\", gap: 12, padding: \"11px 14px\", width: \"100%\", boxSizing: \"border-box\", borderTop: n ? \"1px solid #f0f1f5\" : \"none\" }}>\n                  <span style={{ position: \"relative\" }}>\n                    <Avatar name={name} id={id} />\n                    {unread > 0 && LANG === \"zh\" ? <span style={{ position: \"absolute\", top: -4, right: -4, minWidth: 16, height: 16, borderRadius: 8, background: \"#fa5151\", color: \"#fff\", fontSize: 10.5, fontWeight: 700, display: \"grid\", placeItems: \"center\", padding: \"0 4px\" }}>{unread}</span> : null}\n                  </span>\n                  <span style={{ flex: 1, minWidth: 0 }}>\n                    <span style={{ display: \"flex\", justifyContent: \"space-between\", gap: 8 }}>\n                      <b style={{ fontSize: 15, color: INK }}>{name}</b>\n                      {last && last.time ? <span style={{ fontSize: 11.5, color: unread && LANG === \"es\" ? S.accent : MUTED }}>{String(last.time)}</span> : null}\n                    </span>\n                    <span style={{ display: \"flex\", justifyContent: \"space-between\", gap: 8, marginTop: 2 }}>\n                      <span style={{ fontSize: 13, color: MUTED, whiteSpace: \"nowrap\", overflow: \"hidden\", textOverflow: \"ellipsis\" }}>\n                        {last ? (last.from === \"me\" ? T.me + \": \" : \"\") + String(last.text || \"\") : \"\"}\n                      </span>\n                      {unread > 0 && LANG !== \"zh\" ? <span style={{ minWidth: 18, height: 18, borderRadius: 9, background: S.accent, color: \"#fff\", fontSize: 11, fontWeight: 700, display: \"grid\", placeItems: \"center\", padding: \"0 5px\", flexShrink: 0 }}>{unread}</span> : null}\n                    </span>\n                  </span>\n                </button>\n              );\n            })}\n          </div>\n          <div style={{ display: \"flex\", gap: 8 }}>\n            <input value={newName} onChange={(e) => setNewName(e.target.value)} onKeyDown={(e) => { if (e.key === \"Enter\") startChat(); }} placeholder={T.newChat} style={field} />\n            <button type=\"button\" onClick={startChat} style={sendBtn}>{T.start}</button>\n          </div>\n        </>\n      ) : (\n        <>\n          {moments.length === 0 ? <p style={{ margin: \"8px 2px\", fontSize: 13.5, color: MUTED, textAlign: \"center\" }}>{T.noMoments}</p> : null}\n          {moments.slice().reverse().map((m, ri) => {\n            const i = moments.length - 1 - ri;\n            const author = String(m.author || \"?\");\n            const cs = Array.isArray(m.comments) ? m.comments : [];\n            const likes = (Number(m.likes) || 0) + (m.liked ? 1 : 0);\n            return (\n              <div key={m.id || i} style={{ padding: 14, borderRadius: 16, background: \"#fff\", border: \"1px solid #eceef4\", display: \"grid\", gridTemplateColumns: \"auto 1fr\", gap: \"0 11px\" }}>\n                <Avatar name={author} id={author} size={40} />\n                <div style={{ minWidth: 0, display: \"grid\", gap: 6 }}>\n                  <b style={{ fontSize: 14.5, color: LANG === \"zh\" ? \"#576b95\" : INK }}>{author}</b>\n                  <div style={{ fontSize: 14.5, lineHeight: 1.6, color: INK, whiteSpace: \"pre-wrap\" }}>{String(m.text || \"\")}</div>\n                  <div style={{ display: \"flex\", alignItems: \"center\", justifyContent: \"space-between\" }}>\n                    <span style={{ fontSize: 11.5, color: MUTED }}>{m.time ? String(m.time) : \"\"}</span>\n                    <button type=\"button\" onClick={() => toggleLike(i)} aria-pressed={!!m.liked}\n                      style={{ border: \"none\", borderRadius: 8, cursor: \"pointer\", padding: \"3px 9px\", fontSize: 13, background: m.liked ? \"#ffe3ec\" : \"#f1f2f6\", color: m.liked ? \"#e23c6b\" : \"#5b6075\" }}>\n                      {m.liked ? \"♥\" : \"♡\"}\n                    </button>\n                  </div>\n                  {likes > 0 || cs.length > 0 ? (\n                    <div style={{ display: \"grid\", gap: 3, padding: \"7px 10px\", borderRadius: 8, background: \"#f5f6f8\", fontSize: 13, lineHeight: 1.5 }}>\n                      {likes > 0 ? <span style={{ color: \"#576b95\" }}>♥ {T.likes.replace(\"{n}\", String(likes))}</span> : null}\n                      {cs.map((c, k) => (\n                        <span key={k}><b style={{ color: \"#576b95\", fontWeight: 600 }}>{c.author === \"me\" ? T.me : String(c.author || \"\")}</b>: {String(c.text || \"\")}</span>\n                      ))}\n                    </div>\n                  ) : null}\n                  <input value={comments[i] || \"\"} onChange={(e) => setComments({ ...comments, [i]: e.target.value })}\n                    onKeyDown={(e) => { if (e.key === \"Enter\") addComment(i); }} placeholder={T.comment} style={{ ...field, padding: \"7px 12px\", fontSize: 13 }} />\n                </div>\n              </div>\n            );\n          })}\n        </>\n      )}\n    </div>\n  );\n}\n",
  "places": "// @ts-nocheck\n// Card UI source: React and useYumina are injected globals at runtime.\n//\n// App pack: Places — where the player is, what places they know, and who is where.\n// The AI keeps `app_places` current. \"Go\" sends a turn so the story can move\n// the player there; the AI updates `here` when they arrive.\n\nconst LANG = \"__YUMINA_APP_LANG__\";\nconst VAR = \"app_places\";\n\nconst TABLE = {\n  zh: {\n    name: \"地点\", here: \"你在这里\", known: \"去过和听说过的地方\", go: \"去这里\", action: \"（前往{name}）\",\n    visited: \"去过\", unvisited: \"没去过\", danger: \"危险\", nobody: \"这里没有别人\",\n    empty: \"故事里一出现地方，就会记在这里。\",\n  },\n  en: {\n    name: \"Places\", here: \"You are here\", known: \"Places you know\", go: \"Go\", action: \"(goes to {name})\",\n    visited: \"Visited\", unvisited: \"Not visited\", danger: \"Danger\", nobody: \"Nobody else is here\",\n    empty: \"Places show up here as the story mentions them.\",\n  },\n  es: {\n    name: \"Lugares\", here: \"Estás aquí\", known: \"Lugares que conoces\", go: \"Ir\", action: \"(va a {name})\",\n    visited: \"Visitado\", unvisited: \"Sin visitar\", danger: \"Peligro\", nobody: \"No hay nadie más aquí\",\n    empty: \"Los lugares aparecen aquí cuando la historia los menciona.\",\n  },\n};\nconst T = TABLE[LANG] || TABLE.en;\n\nexport const app = { id: \"places\", icon: \"🗺️\", name: T.name, variable: VAR, accent: \"#3b82f6\", accent2: \"#06b6d4\", lang: LANG };\n\nconst INK = \"#1b1e2b\";\nconst MUTED = \"#737891\";\nconst PALETTE = [[\"#ff5f8f\", \"#ffe3ec\"], [\"#5b7cff\", \"#e3e9ff\"], [\"#19b394\", \"#dcf5ee\"], [\"#f29a1f\", \"#fdefd9\"], [\"#9a5bff\", \"#efe4ff\"], [\"#1aa3e0\", \"#ddf1fb\"], [\"#ef6a3a\", \"#fde6dc\"]];\nfunction colorFor(key) {\n  let h = 0;\n  for (let i = 0; i < key.length; i++) h = (h * 31 + key.charCodeAt(i)) >>> 0;\n  return PALETTE[h % PALETTE.length];\n}\n\nfunction Who({ names, dark }) {\n  const list = Array.isArray(names) ? names : [];\n  if (list.length === 0) return null;\n  return (\n    <span style={{ display: \"flex\", flexWrap: \"wrap\", gap: 5 }}>\n      {list.map((n, i) => {\n        const name = String(n);\n        const [strong, soft] = colorFor(name);\n        return (\n          <span key={i} style={{ display: \"inline-flex\", alignItems: \"center\", gap: 5, padding: \"2px 8px 2px 2px\", borderRadius: 99, fontSize: 12, fontWeight: 600, background: dark ? \"rgba(255,255,255,0.18)\" : soft, color: dark ? \"#fff\" : strong }}>\n            <span style={{ width: 18, height: 18, borderRadius: 9, background: dark ? \"rgba(255,255,255,0.9)\" : \"#fff\", color: strong, display: \"grid\", placeItems: \"center\", fontSize: 10.5, fontWeight: 800 }}>{name.slice(0, 1)}</span>\n            {name}\n          </span>\n        );\n      })}\n    </span>\n  );\n}\n\nfunction Danger({ level }) {\n  const n = Math.max(0, Math.min(3, Number(level) || 0));\n  if (n === 0) return null;\n  return (\n    <span title={T.danger} style={{ display: \"inline-flex\", gap: 3, alignItems: \"center\" }}>\n      {[1, 2, 3].map((i) => (\n        <span key={i} style={{ width: 7, height: 7, borderRadius: 4, background: i <= n ? (n >= 3 ? \"#e5484d\" : n === 2 ? \"#f29a1f\" : \"#f5c542\") : \"#e3e5ec\" }} />\n      ))}\n    </span>\n  );\n}\n\nexport default function Places({ close }) {\n  const api = useYumina();\n  const data = api.variables[VAR] || {};\n  const places = data.places && typeof data.places === \"object\" ? data.places : {};\n  const ids = Object.keys(places);\n  const hereId = typeof data.here === \"string\" && places[data.here] ? data.here : null;\n  const here = hereId ? places[hereId] : null;\n\n  if (ids.length === 0) {\n    return (\n      <div style={{ padding: \"40px 28px\", textAlign: \"center\", color: MUTED, fontSize: 14, lineHeight: 1.7 }}>\n        <div style={{ fontSize: 40, marginBottom: 8 }}>🗺️</div>{T.empty}\n      </div>\n    );\n  }\n\n  const others = ids.filter((id) => id !== hereId);\n  const go = (p, id) => {\n    api.sendMessage(T.action.replace(\"{name}\", String(p.name || id)));\n    if (close) close();\n  };\n\n  return (\n    <div style={{ padding: 14, display: \"grid\", gap: 12 }}>\n      {here ? (\n        <div style={{ borderRadius: 18, padding: 16, color: \"#fff\", background: \"linear-gradient(135deg, #3b82f6, #06b6d4)\", boxShadow: \"0 8px 22px rgba(59,130,246,0.28)\", display: \"grid\", gap: 8 }}>\n          <span style={{ fontSize: 11.5, fontWeight: 700, letterSpacing: \".06em\", opacity: 0.85 }}>📍 {T.here}</span>\n          <span style={{ display: \"flex\", alignItems: \"center\", gap: 12 }}>\n            <span style={{ width: 54, height: 54, borderRadius: 16, background: \"rgba(255,255,255,0.2)\", display: \"grid\", placeItems: \"center\", fontSize: 30, flexShrink: 0 }}>{here.icon || \"📍\"}</span>\n            <span style={{ minWidth: 0, flex: 1 }}>\n              <b style={{ display: \"block\", fontSize: 19 }}>{String(here.name || hereId)}</b>\n              {here.desc ? <span style={{ display: \"block\", fontSize: 13, lineHeight: 1.55, opacity: 0.92, marginTop: 2 }}>{String(here.desc)}</span> : null}\n            </span>\n          </span>\n          {Array.isArray(here.who) && here.who.length > 0\n            ? <Who names={here.who} dark />\n            : <span style={{ fontSize: 12.5, opacity: 0.8 }}>{T.nobody}</span>}\n        </div>\n      ) : null}\n\n      {others.length > 0 ? <div style={{ fontSize: 12, color: MUTED, padding: \"2px 2px 0\" }}>{T.known}</div> : null}\n      {others.map((id) => {\n        const p = places[id] || {};\n        return (\n          <div key={id} style={{ borderRadius: 16, background: \"#fff\", border: \"1px solid #eceef4\", boxShadow: \"0 1px 2px rgba(20,24,40,0.05)\", padding: 12, display: \"grid\", gap: 8 }}>\n            <div style={{ display: \"flex\", alignItems: \"center\", gap: 11 }}>\n              <span style={{ width: 42, height: 42, borderRadius: 13, background: p.visited ? \"#e6efff\" : \"#f1f2f6\", display: \"grid\", placeItems: \"center\", fontSize: 22, flexShrink: 0, filter: p.visited ? \"none\" : \"grayscale(0.4)\" }}>{p.icon || \"📍\"}</span>\n              <span style={{ flex: 1, minWidth: 0 }}>\n                <span style={{ display: \"flex\", alignItems: \"center\", gap: 7, flexWrap: \"wrap\" }}>\n                  <b style={{ fontSize: 15, color: INK }}>{String(p.name || id)}</b>\n                  <Danger level={p.danger} />\n                  <span style={{ fontSize: 11, color: p.visited ? \"#2f6fd1\" : MUTED }}>{p.visited ? T.visited : T.unvisited}</span>\n                </span>\n                {p.desc ? <span style={{ display: \"block\", fontSize: 12.5, color: MUTED, marginTop: 2, whiteSpace: \"nowrap\", overflow: \"hidden\", textOverflow: \"ellipsis\" }}>{String(p.desc)}</span> : null}\n              </span>\n              <button type=\"button\" onClick={() => go(p, id)}\n                style={{ border: \"none\", cursor: \"pointer\", borderRadius: 10, padding: \"7px 13px\", fontSize: 12.5, fontWeight: 700, background: \"#3b82f6\", color: \"#fff\", flexShrink: 0 }}>\n                {T.go}\n              </button>\n            </div>\n            <Who names={p.who} />\n          </div>\n        );\n      })}\n    </div>\n  );\n}\n",
  "relations": "// @ts-nocheck\n// Card UI source: React and useYumina are injected globals at runtime.\n//\n// App pack: Relationships — how every important character feels about the player.\n//\n// How an App pack works (the same for every file in this folder):\n//   - `const VAR` names the ONE json variable this app reads. The AI writes it\n//     (its rules live on the variable); this file only draws it.\n//   - `export const app` puts the app in the dock: icon, name, colours, and an\n//     optional badge(data) count.\n//   - `export default` is the panel body. It may write the variable itself\n//     with api.patchVariables for things the player does that cost no turn.\n//   - LANG is replaced with the card's language when the pack is installed.\n\nconst LANG = \"__YUMINA_APP_LANG__\";\nconst VAR = \"app_relations\";\n\nconst TABLE = {\n  zh: {\n    name: \"角色关系\", labelW: \"2.6em\", affection: \"好感\", trust: \"信任\", note: \"TA 现在怎么看你\", talk: \"对 TA 说…\",\n    draft: \"（对{name}说）\", empty: \"故事里的人一出场，他们的卡片就会出现在这里。\", people: \"{n} 个人\",\n  },\n  en: {\n    name: \"Relationships\", labelW: \"4.9em\", affection: \"Affection\", trust: \"Trust\", note: \"What they think of you\", talk: \"Say something…\",\n    draft: \"(to {name}) \", empty: \"Cards appear here as characters enter the story.\", people: \"{n} people\",\n  },\n  es: {\n    name: \"Relaciones\", labelW: \"5.6em\", affection: \"Afecto\", trust: \"Confianza\", note: \"Lo que piensa de ti\", talk: \"Decirle algo…\",\n    draft: \"(a {name}) \", empty: \"Las tarjetas aparecen aquí cuando los personajes entran en la historia.\", people: \"{n} personas\",\n  },\n};\nconst T = TABLE[LANG] || TABLE.en;\n\nexport const app = { id: \"relations\", icon: \"💞\", name: T.name, variable: VAR, accent: \"#ff5f8f\", accent2: \"#ff9a6b\", lang: LANG };\n\nconst INK = \"#1b1e2b\";\nconst MUTED = \"#737891\";\nconst PALETTE = [[\"#ff5f8f\", \"#ffe3ec\"], [\"#5b7cff\", \"#e3e9ff\"], [\"#19b394\", \"#dcf5ee\"], [\"#f29a1f\", \"#fdefd9\"], [\"#9a5bff\", \"#efe4ff\"], [\"#1aa3e0\", \"#ddf1fb\"], [\"#ef6a3a\", \"#fde6dc\"]];\nfunction colorFor(key) {\n  let h = 0;\n  for (let i = 0; i < key.length; i++) h = (h * 31 + key.charCodeAt(i)) >>> 0;\n  return PALETTE[h % PALETTE.length];\n}\nfunction clamp(n) {\n  const v = Number(n);\n  return Number.isFinite(v) ? Math.max(0, Math.min(100, Math.round(v))) : null;\n}\n\n// What the player saw last time the panel was open: a change shows as +3 / −2\n// until they have looked once.\nconst SEEN = (typeof window !== \"undefined\" && (window.__yumina_app_seen = window.__yumina_app_seen || {})) || {};\n\nfunction Meter({ label, value, prev, from, to }) {\n  const v = clamp(value);\n  if (v === null) return null;\n  const p = clamp(prev);\n  const d = p === null ? 0 : v - p;\n  return (\n    <div style={{ display: \"grid\", gridTemplateColumns: T.labelW + \" 1fr auto\", alignItems: \"center\", gap: 10, fontSize: 12.5 }}>\n      <span style={{ color: MUTED }}>{label}</span>\n      <span style={{ height: 8, borderRadius: 5, background: \"#eef0f5\", overflow: \"hidden\" }}>\n        <span style={{ display: \"block\", height: \"100%\", width: v + \"%\", borderRadius: 5, background: \"linear-gradient(90deg, \" + from + \", \" + to + \")\", transition: \"width .5s\" }} />\n      </span>\n      <span style={{ display: \"flex\", alignItems: \"center\", gap: 5, minWidth: 34, justifyContent: \"flex-end\" }}>\n        {d !== 0 ? (\n          <span style={{ fontSize: 11, fontWeight: 800, padding: \"0 5px\", borderRadius: 6, background: d > 0 ? \"#dcf5e8\" : \"#fde2e2\", color: d > 0 ? \"#12925a\" : \"#d23b3b\" }}>\n            {d > 0 ? \"+\" + d : \"−\" + Math.abs(d)}\n          </span>\n        ) : null}\n        <b style={{ fontVariantNumeric: \"tabular-nums\", color: INK }}>{v}</b>\n      </span>\n    </div>\n  );\n}\n\nexport default function Relations({ close }) {\n  const api = useYumina();\n  const data = api.variables[VAR] || {};\n  const chars = data.chars && typeof data.chars === \"object\" ? data.chars : {};\n  const ids = Object.keys(chars);\n  const [openId, setOpenId] = React.useState(null);\n  const prevRef = React.useRef(SEEN[VAR] || {});\n\n  React.useEffect(() => { SEEN[VAR] = JSON.parse(JSON.stringify(chars)); });\n\n  if (ids.length === 0) {\n    return (\n      <div style={{ padding: \"40px 28px\", textAlign: \"center\", color: MUTED, fontSize: 14, lineHeight: 1.7 }}>\n        <div style={{ fontSize: 40, marginBottom: 8 }}>💞</div>{T.empty}\n      </div>\n    );\n  }\n\n  return (\n    <div style={{ padding: 14, display: \"grid\", gap: 10 }}>\n      <div style={{ fontSize: 12, color: MUTED, padding: \"0 2px\" }}>{T.people.replace(\"{n}\", String(ids.length))}</div>\n      {ids.map((id) => {\n        const c = chars[id] || {};\n        const prev = prevRef.current[id] || {};\n        const name = String(c.name || id);\n        const [strong, soft] = colorFor(id);\n        const open = openId === id;\n        return (\n          <div key={id} style={{ borderRadius: 18, background: \"#fff\", border: \"1px solid #eceef4\", boxShadow: \"0 1px 2px rgba(20,24,40,0.05)\", overflow: \"hidden\" }}>\n            <button type=\"button\" onClick={() => setOpenId(open ? null : id)} aria-expanded={open}\n              style={{ all: \"unset\", cursor: \"pointer\", display: \"grid\", gap: 10, padding: 14, width: \"100%\", boxSizing: \"border-box\" }}>\n              <span style={{ display: \"flex\", alignItems: \"center\", gap: 12 }}>\n                <span style={{ width: 46, height: 46, borderRadius: 23, background: \"linear-gradient(145deg, \" + soft + \", #fff)\", color: strong, border: \"2px solid \" + soft, display: \"grid\", placeItems: \"center\", fontWeight: 800, fontSize: 19, flexShrink: 0 }}>\n                  {name.slice(0, 1)}\n                </span>\n                <span style={{ flex: 1, minWidth: 0 }}>\n                  <span style={{ display: \"flex\", alignItems: \"center\", gap: 7, flexWrap: \"wrap\" }}>\n                    <b style={{ fontSize: 16, color: INK }}>{name}</b>\n                    {c.tag ? <span style={{ fontSize: 11.5, fontWeight: 600, padding: \"2px 8px\", borderRadius: 99, background: soft, color: strong }}>{String(c.tag)}</span> : null}\n                  </span>\n                  {c.mood ? <span style={{ display: \"block\", fontSize: 13, color: MUTED, marginTop: 3 }}>{String(c.mood)}</span> : null}\n                </span>\n                <span aria-hidden=\"true\" style={{ color: \"#b3b7c7\", fontSize: 18, transform: open ? \"rotate(90deg)\" : \"none\", transition: \"transform .15s\" }}>›</span>\n              </span>\n              <Meter label={T.affection} value={c.affection} prev={prev.affection} from=\"#ff7aa2\" to=\"#ff5f8f\" />\n              <Meter label={T.trust} value={c.trust} prev={prev.trust} from=\"#7da2ff\" to=\"#5b7cff\" />\n            </button>\n            {open ? (\n              <div style={{ padding: \"0 14px 14px\", display: \"grid\", gap: 10 }}>\n                {c.note ? (\n                  <div style={{ fontSize: 13.5, lineHeight: 1.65, color: INK, background: \"#f7f8fb\", borderLeft: \"3px solid \" + strong, borderRadius: \"4px 12px 12px 4px\", padding: \"9px 12px\" }}>\n                    <span style={{ display: \"block\", fontSize: 11.5, color: MUTED, marginBottom: 2 }}>{T.note}</span>\n                    {String(c.note)}\n                  </div>\n                ) : null}\n                <button type=\"button\"\n                  onClick={() => { api.setComposerDraft(T.draft.replace(\"{name}\", name)); if (close) close(); }}\n                  style={{ justifySelf: \"start\", border: \"none\", cursor: \"pointer\", borderRadius: 11, padding: \"8px 14px\", fontSize: 13, fontWeight: 700, background: strong, color: \"#fff\" }}>\n                  {T.talk}\n                </button>\n              </div>\n            ) : null}\n          </div>\n        );\n      })}\n    </div>\n  );\n}\n",
  "social": "// @ts-nocheck\n// Card UI source: React and useYumina are injected globals at runtime.\n//\n// App pack: Feed — the public square. NPCs and strangers post about what\n// happens; a trending list shows what the world is talking about (including\n// rumours about the player). Likes, reposts and comments cost no turn: they\n// are written to the variable and the AI notices them next turn. A post the\n// player writes is also sent as a turn so the world can react to it.\n\nconst LANG = \"__YUMINA_APP_LANG__\";\nconst VAR = \"app_social\";\n\nconst TABLE = {\n  zh: {\n    name: \"广场\", forYou: \"推荐\", trending: \"热搜\", compose: \"分享新鲜事…\", post: \"发布\",\n    action: \"（发了一条动态）{text}\", comment: \"写评论…\", me: \"我\", look: \"去看看 #{title}\",\n    empty: \"还没有人发帖。故事里发生的事，大家会在这里议论。\", noTrend: \"热搜榜还是空的。\",\n    tags: { hot: \"爆\", new: \"新\", rising: \"升\" },\n  },\n  en: {\n    name: \"Feed\", forYou: \"For you\", trending: \"Trending\", compose: \"What's happening?\", post: \"Post\",\n    action: \"(posts) {text}\", comment: \"Reply…\", me: \"Me\", look: \"Look into #{title}\",\n    empty: \"No posts yet. When something happens in the story, people talk about it here.\", noTrend: \"Nothing is trending yet.\",\n    tags: { hot: \"HOT\", new: \"NEW\", rising: \"UP\" },\n  },\n  es: {\n    name: \"Tendencias\", forYou: \"Para ti\", trending: \"Tendencias\", compose: \"¿Qué está pasando?\", post: \"Publicar\",\n    action: \"(publica) {text}\", comment: \"Responder…\", me: \"Yo\", look: \"Ver #{title}\",\n    empty: \"Aún no hay publicaciones. Cuando pase algo en la historia, la gente lo comentará aquí.\", noTrend: \"Todavía no hay tendencias.\",\n    tags: { hot: \"HOT\", new: \"NUEVO\", rising: \"SUBE\" },\n  },\n};\nconst T = TABLE[LANG] || TABLE.en;\n\nexport const app = { id: \"social\", icon: \"🔥\", name: T.name, variable: VAR, accent: \"#ff7a3d\", accent2: \"#ff3d6e\", lang: LANG };\n\nconst INK = \"#1b1e2b\";\nconst MUTED = \"#737891\";\nconst ACCENT = \"#ff4d5e\";\nconst PALETTE = [[\"#ff5f8f\", \"#ffe3ec\"], [\"#5b7cff\", \"#e3e9ff\"], [\"#19b394\", \"#dcf5ee\"], [\"#f29a1f\", \"#fdefd9\"], [\"#9a5bff\", \"#efe4ff\"], [\"#1aa3e0\", \"#ddf1fb\"], [\"#ef6a3a\", \"#fde6dc\"]];\nfunction colorFor(key) {\n  let h = 0;\n  for (let i = 0; i < key.length; i++) h = (h * 31 + key.charCodeAt(i)) >>> 0;\n  return PALETTE[h % PALETTE.length];\n}\nconst TAG_COLOR = { hot: \"#ff3b4e\", new: \"#ff8a1f\", rising: \"#3d8bff\" };\nconst card = { borderRadius: 18, background: \"#fff\", border: \"1px solid #eceef4\", boxShadow: \"0 1px 2px rgba(20,24,40,0.05)\" };\nconst inputStyle = { flex: 1, minWidth: 0, borderRadius: 12, border: \"1px solid #e3e6ee\", background: \"#f7f8fb\", color: INK, padding: \"9px 12px\", fontSize: 13.5, outline: \"none\", fontFamily: \"inherit\" };\n\nfunction Avatar({ name, size }) {\n  const [strong, soft] = colorFor(String(name || \"?\"));\n  const s = size || 40;\n  return (\n    <span style={{ width: s, height: s, borderRadius: s / 2, background: \"linear-gradient(145deg, \" + soft + \", #fff)\", color: strong, border: \"2px solid \" + soft, display: \"grid\", placeItems: \"center\", fontWeight: 800, fontSize: s * 0.42, flexShrink: 0 }}>\n      {String(name || \"?\").slice(0, 1)}\n    </span>\n  );\n}\n\nfunction count(n) {\n  const v = Number(n) || 0;\n  if (LANG === \"zh\" && v >= 10000) return (v / 10000).toFixed(1).replace(/\\.0$/, \"\") + \"万\";\n  if (LANG !== \"zh\" && v >= 1000) return (v / 1000).toFixed(1).replace(/\\.0$/, \"\") + \"k\";\n  return String(v);\n}\n\nexport default function Feed({ close }) {\n  const api = useYumina();\n  const data = api.variables[VAR] || {};\n  const posts = Array.isArray(data.posts) ? data.posts : [];\n  const trending = Array.isArray(data.trending) ? data.trending : [];\n  const [tab, setTab] = React.useState(\"feed\");\n  const [draft, setDraft] = React.useState(\"\");\n  const [replies, setReplies] = React.useState({});\n\n  const save = (next) => api.patchVariables({ [VAR]: { ...data, ...next } }).catch(() => {});\n\n  const publish = () => {\n    const text = draft.trim();\n    if (!text) return;\n    save({ posts: [...posts, { id: \"me\" + Date.now().toString(36), author: \"me\", text, likes: 0, reposts: 0, comments: [] }] });\n    api.sendMessage(T.action.replace(\"{text}\", text));\n    setDraft(\"\");\n  };\n  const toggle = (i, key) => save({ posts: posts.map((p, j) => (j === i ? { ...p, [key]: !p[key] } : p)) });\n  const reply = (i) => {\n    const text = String(replies[i] || \"\").trim();\n    if (!text) return;\n    save({ posts: posts.map((p, j) => (j === i ? { ...p, comments: [...(Array.isArray(p.comments) ? p.comments : []), { author: \"me\", text }] } : p)) });\n    setReplies({ ...replies, [i]: \"\" });\n  };\n\n  const tabBtn = (key, label) => (\n    <button type=\"button\" onClick={() => setTab(key)} aria-pressed={tab === key}\n      style={{ flex: 1, border: \"none\", cursor: \"pointer\", padding: \"10px 0 9px\", fontSize: 14.5, fontWeight: tab === key ? 800 : 600, background: \"transparent\", color: tab === key ? INK : MUTED, borderBottom: \"3px solid \" + (tab === key ? ACCENT : \"transparent\") }}>\n      {label}\n    </button>\n  );\n\n  return (\n    <div style={{ display: \"flex\", flexDirection: \"column\" }}>\n      <div style={{ display: \"flex\", background: \"#fff\", borderBottom: \"1px solid #eceef4\", position: \"sticky\", top: 0, zIndex: 1 }}>\n        {tabBtn(\"feed\", T.forYou)}\n        {tabBtn(\"trending\", T.trending)}\n      </div>\n\n      {tab === \"feed\" ? (\n        <div style={{ padding: 14, display: \"grid\", gap: 10 }}>\n          <div style={{ ...card, padding: 12, display: \"flex\", gap: 10, alignItems: \"flex-start\" }}>\n            <Avatar name={T.me} size={36} />\n            <div style={{ flex: 1, display: \"grid\", gap: 8 }}>\n              <textarea value={draft} onChange={(e) => setDraft(e.target.value)} placeholder={T.compose} rows={2}\n                style={{ ...inputStyle, resize: \"none\", lineHeight: 1.5 }} />\n              <button type=\"button\" onClick={publish} disabled={!draft.trim()}\n                style={{ justifySelf: \"end\", border: \"none\", cursor: draft.trim() ? \"pointer\" : \"default\", borderRadius: 99, padding: \"7px 18px\", fontSize: 13, fontWeight: 800, color: \"#fff\", background: \"linear-gradient(135deg, #ff7a3d, #ff3d6e)\", opacity: draft.trim() ? 1 : 0.45 }}>\n                {T.post}\n              </button>\n            </div>\n          </div>\n\n          {posts.length === 0 ? (\n            <div style={{ padding: \"30px 24px\", textAlign: \"center\", color: MUTED, fontSize: 14, lineHeight: 1.7 }}>\n              <div style={{ fontSize: 40, marginBottom: 8 }}>🔥</div>{T.empty}\n            </div>\n          ) : null}\n\n          {posts.slice().reverse().map((p, ri) => {\n            const i = posts.length - 1 - ri;\n            const mine = p.author === \"me\";\n            const author = mine ? T.me : String(p.author || \"?\");\n            const cs = Array.isArray(p.comments) ? p.comments : [];\n            return (\n              <div key={p.id || i} style={{ ...card, padding: 14, display: \"grid\", gap: 9 }}>\n                <div style={{ display: \"flex\", alignItems: \"center\", gap: 10 }}>\n                  <Avatar name={author} size={38} />\n                  <div style={{ flex: 1, minWidth: 0 }}>\n                    <b style={{ fontSize: 14.5, color: INK }}>{author}</b>\n                    <div style={{ fontSize: 12, color: MUTED }}>\n                      {p.handle ? \"@\" + String(p.handle).replace(/^@/, \"\") : \"\"}{p.handle && p.time ? \" · \" : \"\"}{p.time ? String(p.time) : \"\"}\n                    </div>\n                  </div>\n                </div>\n                <div style={{ fontSize: 14.5, lineHeight: 1.65, color: INK, whiteSpace: \"pre-wrap\", wordBreak: \"break-word\" }}>{String(p.text || \"\")}</div>\n                <div style={{ display: \"flex\", gap: 20, fontSize: 13, color: MUTED }}>\n                  <button type=\"button\" onClick={() => toggle(i, \"reposted\")} aria-pressed={!!p.reposted}\n                    style={{ border: \"none\", background: \"transparent\", cursor: \"pointer\", padding: 0, fontSize: 13, color: p.reposted ? \"#12a36b\" : MUTED, fontWeight: p.reposted ? 700 : 500 }}>\n                    ⇄ {count((Number(p.reposts) || 0) + (p.reposted ? 1 : 0))}\n                  </button>\n                  <span>💬 {count(cs.length)}</span>\n                  <button type=\"button\" onClick={() => toggle(i, \"liked\")} aria-pressed={!!p.liked}\n                    style={{ border: \"none\", background: \"transparent\", cursor: \"pointer\", padding: 0, fontSize: 13, color: p.liked ? ACCENT : MUTED, fontWeight: p.liked ? 700 : 500 }}>\n                    {p.liked ? \"♥\" : \"♡\"} {count((Number(p.likes) || 0) + (p.liked ? 1 : 0))}\n                  </button>\n                </div>\n                {cs.length > 0 ? (\n                  <div style={{ display: \"grid\", gap: 5, padding: \"9px 11px\", borderRadius: 12, background: \"#f7f8fb\" }}>\n                    {cs.map((c, k) => (\n                      <div key={k} style={{ fontSize: 13, lineHeight: 1.55, color: INK }}>\n                        <b style={{ color: c.author === \"me\" ? ACCENT : \"#3d63d9\" }}>{c.author === \"me\" ? T.me : String(c.author || \"\")}</b>：{String(c.text || \"\")}\n                      </div>\n                    ))}\n                  </div>\n                ) : null}\n                <input value={replies[i] || \"\"} onChange={(e) => setReplies({ ...replies, [i]: e.target.value })}\n                  onKeyDown={(e) => { if (e.key === \"Enter\") reply(i); }} placeholder={T.comment}\n                  style={{ ...inputStyle, padding: \"7px 11px\", fontSize: 12.5 }} />\n              </div>\n            );\n          })}\n        </div>\n      ) : (\n        <div style={{ padding: 14 }}>\n          {trending.length === 0 ? (\n            <div style={{ padding: \"30px 24px\", textAlign: \"center\", color: MUTED, fontSize: 14 }}>\n              <div style={{ fontSize: 40, marginBottom: 8 }}>📈</div>{T.noTrend}\n            </div>\n          ) : (\n            <div style={{ ...card, overflow: \"hidden\" }}>\n              {trending.slice(0, 10).map((t, i) => {\n                const tag = String(t.tag || \"\");\n                const rankColor = i === 0 ? \"#ff3b4e\" : i === 1 ? \"#ff6a2b\" : i === 2 ? \"#f5a524\" : \"#a3a8ba\";\n                return (\n                  <button key={t.id || i} type=\"button\"\n                    onClick={() => { api.setComposerDraft(T.look.replace(\"{title}\", String(t.title || \"\"))); if (close) close(); }}\n                    style={{ all: \"unset\", cursor: \"pointer\", display: \"flex\", alignItems: \"center\", gap: 12, padding: \"12px 14px\", width: \"100%\", boxSizing: \"border-box\", borderTop: i ? \"1px solid #f0f1f5\" : \"none\" }}>\n                    <b style={{ width: 20, textAlign: \"center\", fontSize: 16, fontStyle: \"italic\", color: rankColor, fontVariantNumeric: \"tabular-nums\" }}>{i + 1}</b>\n                    <span style={{ flex: 1, minWidth: 0 }}>\n                      <span style={{ display: \"flex\", alignItems: \"center\", gap: 6 }}>\n                        <span style={{ fontSize: 14.5, fontWeight: 600, color: INK, overflow: \"hidden\", textOverflow: \"ellipsis\", whiteSpace: \"nowrap\" }}>#{String(t.title || \"\")}</span>\n                        {TAG_COLOR[tag] ? <span style={{ flexShrink: 0, fontSize: 10.5, fontWeight: 800, color: \"#fff\", background: TAG_COLOR[tag], borderRadius: 5, padding: \"1px 5px\" }}>{T.tags[tag]}</span> : null}\n                      </span>\n                      {t.heat ? <span style={{ display: \"block\", fontSize: 12, color: MUTED, marginTop: 2 }}>{String(t.heat)}</span> : null}\n                    </span>\n                    <span aria-hidden=\"true\" style={{ color: \"#b3b7c7\", fontSize: 18 }}>›</span>\n                  </button>\n                );\n              })}\n            </div>\n          )}\n        </div>\n      )}\n    </div>\n  );\n}\n",
  "status": "// @ts-nocheck\n// Card UI source: React and useYumina are injected globals at runtime.\n//\n// App pack: Status — the numbers this story runs on. Bars for anything that\n// fills and drains (health, stamina, reputation, danger…) and a grid of short\n// labels (level, title, condition…). The AI chooses bars that fit the story at\n// the opening and moves them; this file draws them with +n / −n since last look.\n\nconst LANG = \"__YUMINA_APP_LANG__\";\nconst VAR = \"app_status\";\n\nconst TABLE = {\n  zh: { name: \"状态\", empty: \"故事开始后，这里会出现和这个故事有关的数值。\", details: \"详情\" },\n  en: { name: \"Status\", empty: \"Once the story starts, the numbers that matter in it show up here.\", details: \"Details\" },\n  es: { name: \"Estado\", empty: \"Cuando empiece la historia, aquí aparecerán los valores que importan en ella.\", details: \"Detalles\" },\n};\nconst T = TABLE[LANG] || TABLE.en;\n\nexport const app = { id: \"status\", icon: \"📊\", name: T.name, variable: VAR, accent: \"#10b981\", accent2: \"#0ea5e9\", lang: LANG };\n\nconst INK = \"#1b1e2b\";\nconst MUTED = \"#737891\";\nconst FALLBACK = [\"#10b981\", \"#3d8bff\", \"#ff5f8f\", \"#f5a524\", \"#9a5bff\", \"#0ea5e9\", \"#ef6a3a\"];\nconst card = { borderRadius: 18, background: \"#fff\", border: \"1px solid #eceef4\", boxShadow: \"0 1px 2px rgba(20,24,40,0.05)\" };\n\nconst SEEN = (typeof window !== \"undefined\" && (window.__yumina_app_seen = window.__yumina_app_seen || {})) || {};\n\nfunction num(n, d) {\n  const v = Number(n);\n  return Number.isFinite(v) ? v : d;\n}\nfunction lighten(hex) {\n  const m = /^#?([0-9a-f]{6})$/i.exec(String(hex || \"\"));\n  if (!m) return hex;\n  const n = parseInt(m[1], 16);\n  const mix = (c) => Math.round(c + (255 - c) * 0.35);\n  return \"rgb(\" + mix((n >> 16) & 255) + \",\" + mix((n >> 8) & 255) + \",\" + mix(n & 255) + \")\";\n}\n\nexport default function Status() {\n  const api = useYumina();\n  const data = api.variables[VAR] || {};\n  const bars = Array.isArray(data.bars) ? data.bars : [];\n  const tags = Array.isArray(data.tags) ? data.tags : [];\n  const prevRef = React.useRef(SEEN[VAR] || {});\n\n  React.useEffect(() => {\n    const snap = {};\n    bars.forEach((b, i) => { snap[b.id || b.label || i] = num(b.value, 0); });\n    SEEN[VAR] = snap;\n  });\n\n  if (bars.length === 0 && tags.length === 0) {\n    return (\n      <div style={{ padding: \"40px 28px\", textAlign: \"center\", color: MUTED, fontSize: 14, lineHeight: 1.7 }}>\n        <div style={{ fontSize: 40, marginBottom: 8 }}>📊</div>{T.empty}\n      </div>\n    );\n  }\n\n  return (\n    <div style={{ padding: 14, display: \"grid\", gap: 10 }}>\n      {bars.length > 0 ? (\n        <div style={{ ...card, padding: \"6px 16px\" }}>\n          {bars.map((b, i) => {\n            const key = b.id || b.label || i;\n            const max = Math.max(1, num(b.max, 100));\n            const value = Math.max(0, Math.min(max, num(b.value, 0)));\n            const prev = prevRef.current[key];\n            const d = prev === undefined ? 0 : Math.round((value - prev) * 10) / 10;\n            const color = /^#[0-9a-f]{6}$/i.test(String(b.color || \"\")) ? b.color : FALLBACK[i % FALLBACK.length];\n            return (\n              <div key={key} style={{ padding: \"12px 0\", borderTop: i ? \"1px solid #f0f1f5\" : \"none\", display: \"grid\", gap: 7 }}>\n                <div style={{ display: \"flex\", alignItems: \"baseline\", gap: 8 }}>\n                  <b style={{ fontSize: 14.5, color: INK, flex: 1 }}>{String(b.label || b.id || \"\")}</b>\n                  {d !== 0 ? (\n                    <span style={{ fontSize: 11, fontWeight: 800, padding: \"1px 6px\", borderRadius: 6, background: d > 0 ? \"#dcf5e8\" : \"#fde2e2\", color: d > 0 ? \"#12925a\" : \"#d23b3b\" }}>\n                      {d > 0 ? \"+\" + d : \"−\" + Math.abs(d)}\n                    </span>\n                  ) : null}\n                  <span style={{ fontVariantNumeric: \"tabular-nums\", fontSize: 13, color: MUTED }}>\n                    <b style={{ fontSize: 18, color: INK }}>{value}</b> / {max}\n                  </span>\n                </div>\n                <span style={{ height: 12, borderRadius: 7, background: \"#eef0f5\", overflow: \"hidden\" }}>\n                  <span style={{ display: \"block\", height: \"100%\", width: (value / max) * 100 + \"%\", borderRadius: 7, background: \"linear-gradient(90deg, \" + lighten(color) + \", \" + color + \")\", transition: \"width .5s\" }} />\n                </span>\n                {b.note ? <span style={{ fontSize: 12.5, color: MUTED, lineHeight: 1.5 }}>{String(b.note)}</span> : null}\n              </div>\n            );\n          })}\n        </div>\n      ) : null}\n\n      {tags.length > 0 ? (\n        <div style={{ display: \"grid\", gridTemplateColumns: \"repeat(2, minmax(0, 1fr))\", gap: 8 }}>\n          {tags.map((t, i) => (\n            <div key={i} style={{ ...card, borderRadius: 14, padding: \"10px 12px\", display: \"grid\", gap: 2 }}>\n              <span style={{ fontSize: 11.5, color: MUTED }}>{String(t.label || \"\")}</span>\n              <b style={{ fontSize: 14, color: INK, lineHeight: 1.4, wordBreak: \"break-word\" }}>{String(t.value ?? \"\")}</b>\n            </div>\n          ))}\n        </div>\n      ) : null}\n    </div>\n  );\n}\n",
  "time": "// @ts-nocheck\n// Card UI source: React and useYumina are injected globals at runtime.\n//\n// App pack: Time & Plans — the story's clock and the player's appointments.\n// The AI keeps `app_time` current. The player can add a plan or tick one off\n// without spending a turn; the AI sees it in the variable next turn (items the\n// player added carry by:\"player\").\n\nconst LANG = \"__YUMINA_APP_LANG__\";\nconst VAR = \"app_time\";\n\nconst TABLE = {\n  zh: {\n    name: \"时间与日程\", day: \"第 {n} 天\", plans: \"日程\", empty: \"还没有安排。约好的事、要赴的会，会自动记在这里。\",\n    add: \"加一条自己的安排…\", addBtn: \"添加\", done: \"完成\", mine: \"我加的\", noClock: \"故事的时间还没开始走\", doneTitle: \"已完成\",\n    periods: { dawn: \"黎明\", morning: \"上午\", noon: \"中午\", afternoon: \"下午\", evening: \"傍晚\", night: \"夜晚\", late: \"深夜\" },\n  },\n  en: {\n    name: \"Time & Plans\", day: \"Day {n}\", plans: \"Plans\", empty: \"Nothing planned yet. Appointments and promises show up here on their own.\",\n    add: \"Add a plan of your own…\", addBtn: \"Add\", done: \"Done\", mine: \"Mine\", noClock: \"Story time hasn't started yet\", doneTitle: \"Done\",\n    periods: { dawn: \"Dawn\", morning: \"Morning\", noon: \"Noon\", afternoon: \"Afternoon\", evening: \"Evening\", night: \"Night\", late: \"Late night\" },\n  },\n  es: {\n    name: \"Tiempo y agenda\", day: \"Día {n}\", plans: \"Agenda\", empty: \"Nada en la agenda. Las citas y promesas aparecen aquí solas.\",\n    add: \"Añadir un plan propio…\", addBtn: \"Añadir\", done: \"Hecho\", mine: \"Mío\", noClock: \"El tiempo de la historia aún no empieza\", doneTitle: \"Hecho\",\n    periods: { dawn: \"Amanecer\", morning: \"Mañana\", noon: \"Mediodía\", afternoon: \"Tarde\", evening: \"Atardecer\", night: \"Noche\", late: \"Madrugada\" },\n  },\n};\nconst T = TABLE[LANG] || TABLE.en;\n\nexport const app = { id: \"time\", icon: \"🕐\", name: T.name, variable: VAR, accent: \"#ffb020\", accent2: \"#ff7a3d\", lang: LANG };\n\nconst INK = \"#1b1e2b\";\nconst MUTED = \"#737891\";\nconst SKY = {\n  dawn: [\"#ffb088\", \"#8b6fd6\", \"🌅\"], morning: [\"#6cc4ff\", \"#3f7fe0\", \"☀️\"], noon: [\"#4fb3ff\", \"#2a6ad6\", \"☀️\"],\n  afternoon: [\"#ffc46b\", \"#e5774a\", \"🌤️\"], evening: [\"#ff8a66\", \"#7a3f98\", \"🌇\"], night: [\"#34479a\", \"#141b3d\", \"🌙\"],\n  late: [\"#252c63\", \"#0b0f26\", \"🌌\"],\n};\n\nexport default function TimeApp() {\n  const api = useYumina();\n  const data = api.variables[VAR] || {};\n  const agenda = Array.isArray(data.agenda) ? data.agenda : [];\n  const period = typeof data.period === \"string\" && SKY[data.period] ? data.period : null;\n  const sky = SKY[period || \"morning\"];\n  const [draft, setDraft] = React.useState(\"\");\n  const hasClock = data.day || data.clock || data.date || period;\n  const open = agenda.map((it, i) => [it, i]).filter(([it]) => !it.done);\n  const done = agenda.map((it, i) => [it, i]).filter(([it]) => it.done);\n\n  const save = (nextAgenda) => { api.patchVariables({ [VAR]: { ...data, agenda: nextAgenda } }).catch(() => {}); };\n  const toggle = (i) => save(agenda.map((it, j) => (j === i ? { ...it, done: !it.done } : it)));\n  const remove = (i) => save(agenda.filter((_, j) => j !== i));\n  const add = () => {\n    const what = draft.trim();\n    if (!what) return;\n    save([...agenda, { id: \"p\" + Date.now().toString(36), when: \"\", what, done: false, by: \"player\" }]);\n    setDraft(\"\");\n  };\n\n  const Row = ({ it, i }) => (\n    <div style={{ display: \"grid\", gridTemplateColumns: \"26px 1fr auto\", gap: 11, alignItems: \"start\", padding: \"12px 14px\", borderRadius: 16, background: \"#fff\", border: \"1px solid #eceef4\", boxShadow: \"0 1px 2px rgba(20,24,40,0.05)\" }}>\n      <button type=\"button\" onClick={() => toggle(i)} aria-label={T.done} aria-pressed={!!it.done}\n        style={{ width: 24, height: 24, borderRadius: 12, border: \"2px solid \" + (it.done ? \"#19b36b\" : \"#c9cdda\"), background: it.done ? \"#19b36b\" : \"#fff\", color: \"#fff\", cursor: \"pointer\", fontSize: 13, fontWeight: 900, padding: 0 }}>\n        {it.done ? \"✓\" : \"\"}\n      </button>\n      <div style={{ minWidth: 0 }}>\n        <div style={{ fontSize: 14.5, lineHeight: 1.5, color: it.done ? MUTED : INK, textDecoration: it.done ? \"line-through\" : \"none\" }}>{String(it.what || \"\")}</div>\n        <div style={{ display: \"flex\", gap: 6, flexWrap: \"wrap\", marginTop: 4 }}>\n          {it.when ? <span style={{ fontSize: 11.5, fontWeight: 600, padding: \"1px 8px\", borderRadius: 99, background: \"#fff1dc\", color: \"#b86b00\" }}>{String(it.when)}</span> : null}\n          {it.with ? <span style={{ fontSize: 11.5, padding: \"1px 8px\", borderRadius: 99, background: \"#eef0f5\", color: \"#5b6075\" }}>{String(it.with)}</span> : null}\n          {it.by === \"player\" ? <span style={{ fontSize: 11.5, padding: \"1px 8px\", borderRadius: 99, background: \"#e8ebff\", color: \"#4f5bd5\" }}>{T.mine}</span> : null}\n        </div>\n      </div>\n      {it.by === \"player\" ? (\n        <button type=\"button\" onClick={() => remove(i)} aria-label=\"×\"\n          style={{ border: \"none\", background: \"transparent\", color: \"#a3a8ba\", cursor: \"pointer\", fontSize: 18, padding: 0, lineHeight: 1 }}>×</button>\n      ) : <span />}\n    </div>\n  );\n\n  return (\n    <div style={{ padding: 14, display: \"grid\", gap: 12 }}>\n      <div style={{ borderRadius: 20, padding: \"18px 18px 16px\", color: \"#fff\", background: \"linear-gradient(135deg, \" + sky[0] + \", \" + sky[1] + \")\", boxShadow: \"0 8px 20px rgba(30,40,80,0.18)\" }}>\n        {hasClock ? (\n          <>\n            <div style={{ display: \"flex\", justifyContent: \"space-between\", alignItems: \"flex-start\", gap: 10 }}>\n              <div>\n                <div style={{ fontSize: 13, opacity: 0.9, fontWeight: 600 }}>{data.day ? T.day.replace(\"{n}\", String(data.day)) : \"\"}</div>\n                <div style={{ fontSize: 42, fontWeight: 800, lineHeight: 1.1, letterSpacing: \"-.01em\", fontVariantNumeric: \"tabular-nums\" }}>{data.clock || (period ? T.periods[period] : \"\")}</div>\n              </div>\n              <span style={{ fontSize: 40 }} aria-hidden=\"true\">{sky[2]}</span>\n            </div>\n            <div style={{ display: \"flex\", gap: 6, flexWrap: \"wrap\", marginTop: 10, fontSize: 12.5 }}>\n              {period && data.clock ? <span style={{ padding: \"3px 10px\", borderRadius: 99, background: \"rgba(255,255,255,0.22)\" }}>{T.periods[period]}</span> : null}\n              {data.date ? <span style={{ padding: \"3px 10px\", borderRadius: 99, background: \"rgba(255,255,255,0.22)\" }}>{String(data.date)}</span> : null}\n              {data.weather ? <span style={{ padding: \"3px 10px\", borderRadius: 99, background: \"rgba(255,255,255,0.22)\" }}>{String(data.weather)}</span> : null}\n            </div>\n          </>\n        ) : (\n          <div style={{ fontSize: 14, opacity: 0.95 }}>{T.noClock}</div>\n        )}\n      </div>\n\n      <b style={{ fontSize: 13, color: MUTED, padding: \"4px 2px 0\" }}>{T.plans}</b>\n      {agenda.length === 0 ? <p style={{ margin: \"0 2px\", fontSize: 13.5, color: MUTED, lineHeight: 1.7 }}>{T.empty}</p> : null}\n      {open.map(([it, i]) => <Row key={it.id || i} it={it} i={i} />)}\n      {done.length > 0 ? <span style={{ fontSize: 12, color: MUTED, padding: \"2px 2px 0\" }}>{T.doneTitle}</span> : null}\n      {done.map(([it, i]) => <Row key={it.id || i} it={it} i={i} />)}\n\n      <div style={{ display: \"flex\", gap: 8, marginTop: 2 }}>\n        <input value={draft} onChange={(e) => setDraft(e.target.value)} onKeyDown={(e) => { if (e.key === \"Enter\") add(); }}\n          placeholder={T.add}\n          style={{ flex: 1, minWidth: 0, borderRadius: 12, border: \"1px solid #dfe2ea\", background: \"#fff\", color: INK, padding: \"10px 12px\", fontSize: 14, outline: \"none\" }} />\n        <button type=\"button\" onClick={add}\n          style={{ border: \"none\", borderRadius: 12, padding: \"0 16px\", fontWeight: 700, fontSize: 13.5, cursor: \"pointer\", background: \"linear-gradient(145deg,#ffb020,#ff7a3d)\", color: \"#fff\" }}>{T.addBtn}</button>\n      </div>\n    </div>\n  );\n}\n",
};
